// A changed answer ordering must not attach the correction to the wrong option.
const ids=new Set(scenarioQuestions.map(q=>q.id));
for(const [id,entry] of Object.entries(scenarioFeedback)){
  if(!ids.has(id))throw Error('Unknown scenario feedback: '+id);
  const q=scenarioQuestions.find(q=>q.id===id),answers=q.answers||[q.answer];
  if(entry.traps.length!==q.options.length||entry.steps.length!==3)throw Error('Invalid scenario feedback structure: '+id);
  entry.traps.forEach((text,index)=>{if(answers.includes(index)?text!=='':!text)throw Error('Scenario answer/feedback mismatch: '+id+' option '+index)});
}
if(ids.size!==Object.keys(scenarioFeedback).length)throw Error('Scenario feedback does not cover every question');
